import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
cnt = {}
first = {}
last = {}
for idx in range(n):
    x = a[idx]
    cnt[x] = cnt.get(x, 0) + 1
    if x not in first:
        first[x] = idx
    last[x] = idx
deg = max(cnt.values())
best = n
for x in cnt:
    if cnt[x] == deg:
        span = last[x] - first[x] + 1
        if span < best:
            best = span
print(best)

